        'milli', 'millisecond' => (int) (round($this->f * Carbon::MICROSECONDS_PER_SECOND) /
            Carbon::MICROSECONDS_PER_MILLISECOND),
        'micro', 'microsecond' => (int) round($this->f * Carbon::MICROSECONDS_PER_SECOND),
